//! Optional disk storage for complete native components. Package admission
//! supplies the compiler/source/snapshot namespace; the current completed Build
//! adds its exact attachments, generated bytes and optimization request.
//! Every hit re-enters native derivation admission before joining a consumer.
use compilation_products::{IndependentComponentProduct, PreparedPackageBuild};
use optimization_core::digest_encoder::{DomainDigestEncoder, content_identity};
use package_compilation::CompilerProductRetention;
use std::fs;
use std::io::{Read, Write};
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};

const MAGIC: &[u8; 8] = b"OMGNC01\0";
const MAX_BYTES: usize = 128 * 1024 * 1024;
static NEXT_WRITE: AtomicU64 = AtomicU64::new(0);

pub(super) struct ComponentProductCache {
    retention: CompilerProductRetention,
    key: [u8; 32],
    package: semantic_vocabulary::PackageKeyIdentity,
    path: PathBuf,
}

impl ComponentProductCache {
    pub fn for_build(build: &PreparedPackageBuild) -> Result<Option<Self>, String> {
        let Some(retention) = build.package_inputs().native_product_retention().cloned() else {
            return Ok(None);
        };
        let mut digest = DomainDigestEncoder::new(b"omega-native-component-inputs-v1\0");
        digest.raw(retention.input_key());
        digest.raw(&build.native_product_input_identity()?);
        digest.raw(&package_compilation::review_cache_inputs_digest(
            build.package_inputs(),
        ));
        digest.raw(&package_compilation::generated_source_bundle_digest(
            build.generated_source_bundle(),
        ));
        digest.bytes(&build.optimization_rollback().requested_disabled().encode());
        digest.bytes(&build.build().config.settings.optimizations.encode());
        let key = digest.finish();
        let mut name = String::with_capacity(68);
        for byte in key {
            use std::fmt::Write;
            write!(&mut name, "{byte:02x}").expect("String write");
        }
        name.push_str(".rec");
        let path = retention.directory().join("native-terminal").join(name);
        Ok(Some(Self {
            retention,
            key,
            package: build.package_inputs().root(),
            path,
        }))
    }

    fn require_current_compiler(&self) -> Result<(), String> {
        let current = crate::compiler_input_identity()?;
        if current != *self.retention.compiler_identity() {
            return Err(
                "compiler or selected toolchain library changed during component production"
                    .to_owned(),
            );
        }
        Ok(())
    }

    pub fn load(&self) -> Result<Option<IndependentComponentProduct>, String> {
        self.require_current_compiler()?;
        let file = match fs::File::open(&self.path) {
            Ok(file) => file,
            Err(reason) if reason.kind() == std::io::ErrorKind::NotFound => {
                if phase_profile::enabled() {
                    eprintln!("native component retention miss: {}", self.path.display());
                }
                return Ok(None);
            }
            Err(reason) => return Err(format!("open native component retention: {reason}")),
        };
        let mut bytes = Vec::new();
        file.take((MAX_BYTES + 81) as u64)
            .read_to_end(&mut bytes)
            .map_err(|reason| format!("read native component retention: {reason}"))?;
        if bytes.len() < 80
            || bytes.len() > MAX_BYTES + 80
            || &bytes[..8] != MAGIC
            || bytes[8..40] != self.key
        {
            return Err(
                "native component retention has a foreign key/schema or invalid size".to_owned(),
            );
        }
        let length = u64::from_le_bytes(
            bytes[72..80]
                .try_into()
                .map_err(|reason| format!("native component retention length: {reason}"))?,
        );
        if length != (bytes.len() - 80) as u64 || bytes[40..72] != content_identity(&bytes[80..]) {
            return Err(
                "native component retention is truncated or has a different content digest"
                    .to_owned(),
            );
        }
        let product = IndependentComponentProduct::recover_retained(self.package, &bytes[80..])?;
        self.require_current_compiler()?;
        if phase_profile::enabled() {
            eprintln!("native component retention hit: {}", self.path.display());
        }
        Ok(Some(product))
    }

    pub fn store(&self, product: &IndependentComponentProduct) -> Result<(), String> {
        let Some(payload) = product.encode_retained()? else {
            return Ok(());
        };
        if payload.len() > MAX_BYTES {
            return Err("native component retention exceeds its byte bound".to_owned());
        }
        self.require_current_compiler()?;
        let directory = self
            .path
            .parent()
            .ok_or("native component retention has no directory")?;
        fs::create_dir_all(directory)
            .map_err(|reason| format!("create native component retention directory: {reason}"))?;
        let temporary = directory.join(format!(
            ".{}-{}.tmp",
            std::process::id(),
            NEXT_WRITE.fetch_add(1, Ordering::Relaxed)
        ));
        let write = (|| {
            let mut file = fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(&temporary)
                .map_err(|reason| {
                    format!("create native component retention temporary: {reason}")
                })?;
            file.write_all(MAGIC)
                .and_then(|_| file.write_all(&self.key))
                .and_then(|_| file.write_all(&content_identity(&payload)))
                .and_then(|_| file.write_all(&(payload.len() as u64).to_le_bytes()))
                .and_then(|_| file.write_all(&payload))
                .map_err(|reason| format!("write native component retention: {reason}"))?;
            drop(file);
            self.require_current_compiler()?;
            match fs::rename(&temporary, &self.path) {
                Ok(()) => Ok(()),
                Err(reason) if reason.kind() == std::io::ErrorKind::AlreadyExists => {
                    fs::remove_file(&self.path).map_err(|reason| {
                        format!("replace native component retention: {reason}")
                    })?;
                    fs::rename(&temporary, &self.path)
                        .map_err(|reason| format!("publish native component retention: {reason}"))
                }
                Err(reason) => Err(format!("publish native component retention: {reason}")),
            }
        })();
        if temporary.exists() {
            let _ = fs::remove_file(&temporary);
        }
        write?;
        prune(directory)?;
        phase_profile::count("component.cache.retained", 1);
        Ok(())
    }
}

/// Optional cache failures remain visible in an explicitly requested profile;
/// the normal compilation continues through its fresh source route.
pub(super) fn report_miss(reason: &str) {
    phase_profile::count("component.cache.invalid", 1);
    if phase_profile::enabled() {
        eprintln!("native component retention ignored: {reason}");
    }
}

fn prune(directory: &std::path::Path) -> Result<(), String> {
    let mut records = Vec::new();
    let mut bytes = 0u64;
    for entry in fs::read_dir(directory)
        .map_err(|reason| format!("inspect native component retention directory: {reason}"))?
    {
        let entry = entry
            .map_err(|reason| format!("inspect native component retention entry: {reason}"))?;
        if entry
            .path()
            .extension()
            .is_none_or(|extension| extension != "rec")
        {
            continue;
        }
        let metadata = entry
            .metadata()
            .map_err(|reason| format!("inspect native component retention metadata: {reason}"))?;
        if !metadata.is_file() {
            continue;
        }
        bytes = bytes.saturating_add(metadata.len());
        records.push((
            metadata.modified().unwrap_or(std::time::UNIX_EPOCH),
            entry.path(),
            metadata.len(),
        ));
    }
    records.sort_unstable();
    let mut count = records.len();
    for (_, path, length) in records {
        if count <= 256 && bytes <= 512 * 1024 * 1024 {
            break;
        }
        fs::remove_file(path)
            .map_err(|reason| format!("prune native component retention: {reason}"))?;
        count -= 1;
        bytes = bytes.saturating_sub(length);
    }
    Ok(())
}
